package minstack

import "testing"

func TestMinStackBasic(t *testing.T) {
	s := NewMinStack()
	s.Push(5)
	s.Push(3)
	s.Push(7)
	if s.GetMin() != 3 {
		t.Errorf("expected min=3, got %d", s.GetMin())
	}
	s.Pop()
	if s.GetMin() != 3 {
		t.Errorf("after popping 7 min should still be 3, got %d", s.GetMin())
	}
	s.Pop()
	if s.GetMin() != 5 {
		t.Errorf("after popping 3 min should be 5, got %d", s.GetMin())
	}
}

func TestMinStackOrder(t *testing.T) {
	s := NewMinStack()
	s.Push(3)
	s.Push(1)
	s.Push(2)
	s.Pop()
	if s.GetMin() != 1 {
		t.Errorf("expected min=1 after popping 2, got %d", s.GetMin())
	}
	s.Pop()
	if s.GetMin() != 3 {
		t.Errorf("expected min=3 after popping 1, got %d", s.GetMin())
	}
}

func TestMinStackSameValues(t *testing.T) {
	s := NewMinStack()
	s.Push(1)
	s.Push(1)
	s.Pop()
	if s.GetMin() != 1 {
		t.Errorf("expected min=1 after popping duplicate, got %d", s.GetMin())
	}
	if s.Top() != 1 {
		t.Errorf("expected top=1, got %d", s.Top())
	}
}
